export const pct=x=>!present(x)?'Unknown':`${(x*100).toFixed(1)}%`;
const number=x=>!present(x)?'Unknown':Number(x).toLocaleString('en-US',{maximumFractionDigits:2});
const date=x=>x?String(x).slice(0,10):'Not returned';
