const table=(head,rows,cls='')=>`<table class="${cls}">${head?`<thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead>`:''}<tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<${!head&&i===0?'th':'td'}>${esc(v)}</${!head&&i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table>`;
