const card=(label,value,note='',cls='')=>`<div class="metric ${cls}"><div class="label">${esc(label)}</div><strong>${esc(value)}</strong>${note?`<div class="note">${esc(note)}</div>`:''}</div>`;
const financialLabels=m=>m.costCompleteness.materialCostsIncomplete?{gross:'Gross spread before unentered expenses',roi:'Illustrative ROI — incomplete costs',roiNote:'entered costs only · not a fully underwritten return'}:{gross:'Gross spread before other costs',roi:'Project ROI',roiNote:'profit / total project cost'};
const photoCategoryLabel=category=>({EXTERIOR:'Exterior Photo',INTERIOR:'Interior Photo',KITCHEN:'Kitchen Photo',BATHROOM:'Bathroom Photo',ROOF:'Roof Photo',FOUNDATION:'Property Condition Photo',REPAIRS_DAMAGE:'Property Condition Photo',CONDITION:'Property Condition Photo',LANDSCAPING:'Exterior Photo',OTHER:'Property Photo'})[category]??'Property Photo';
export const propertyPhotoCaption=photo=>String(photo?.caption??'').trim()||photoCategoryLabel(photo?.category);
