  const hypothesis=`At a ${money(m.economics.purchasePrice.value)} acquisition, ${money(m.economics.rehab.value)} rehabilitation scope and ${money(m.economics.resaleValue.value)} exit, this saved scenario produces ${money(e.modeledProfit)} after the costs currently entered.`;
