const photoNotice='<p class="photo-evidence-notice"><b>Photo evidence boundary.</b> Photographs were supplied by the report preparer or identified source. Image dates, condition and authenticity have not been independently verified by Property Intelligence. Photographs do not replace an on-site inspection. A CLEAN malware scan confirms file safety only.</p>';
function propertyPhotoPages(photos=[]){
  if(!photos.length)return [];
  // The overview has one full-width cover row and one two-photo row. Keeping it
  // to three images prevents an implicit CSS grid row from spilling onto an
  // orphan continuation page in Chromium's paged-media layout.
  const cover=reportCoverPhoto(photos),ordered=cover?[cover,...photos.filter(item=>item!==cover)]:[...photos],overview=ordered.slice(0,3),remaining=ordered.slice(3),pages=[];
  const figure=item=>`<figure class="report-photo"><img src="${esc(item.dataUrl)}" alt="${esc(propertyPhotoCaption(item.photo))}"><figcaption><b>${esc(propertyPhotoCaption(item.photo))}</b><span>${esc(propertyPhotoDateLabel(item.photo))}${item.photo.sourceDescription?` · Source: ${esc(item.photo.sourceDescription)}`:''}</span></figcaption></figure>`;
  pages.push(`<h1>Property photo overview</h1><p>Selected property imagery associated with this exact saved scenario revision.</p><div class="photo-overview">${overview.map(figure).join('')}</div>${photoNotice}`);
  for(let offset=0;offset<remaining.length;offset+=6)pages.push(`<h1>Property Condition &amp; Rehabilitation Photos${remaining.length>6?` · ${Math.floor(offset/6)+1}`:''}</h1><div class="photo-gallery-report">${remaining.slice(offset,offset+6).map(figure).join('')}</div>${photoNotice}`);
  return pages;
}
function recordedSales(m,heading='Recorded-sale research',standalone=true,comparables=m.comparables,continuation=null){
  const rank={PRIMARY:0,SECONDARY:1,NOT_CLASSIFIED:2,EXCLUDED:3},ordered=[...comparables].sort((a,b)=>rank[a.role]-rank[b.role]);
  const rows=ordered.map(c=>`<tr><td><span class="comp-role ${c.role.toLowerCase()}">${esc(c.role.replaceAll('_',' '))}</span><br><b>${esc(c.address.value)}</b>${c.observationCount>1?`<br><span class="comp-identity">${c.observationCount} source observations · one logical transaction</span>`:''}</td><td>${esc(date(c.saleDate.value))}<br><b>${esc(money(c.salePrice.value))}</b></td><td>${esc(number(c.livingAreaSqft.value))} SF<br>${esc(number(c.distanceMiles.value))} mi · ${esc(number(c.bedrooms.value))}/${esc(number(c.bathrooms.value))}</td><td><b>${esc(c.status)}</b><br>${esc(c.analystRationale||'No rationale or adjustment documented.')}${c.reviewFlags.length?`<br><span class="comp-warning">${esc(c.reviewFlags.join(' '))}</span>`:''}</td></tr>`).join('');
  const counts=`<div class="comp-counts"><span><b>${m.research.primary}</b> Primary</span><span><b>${m.research.secondary}</b> Secondary</span><span><b>${m.research.unclassified}</b> Unclassified</span><span><b>${m.research.excluded}</b> Excluded</span></div>`;
  const privateReferences=`<!-- private comparable audit references: ${m.comparables.map(c=>esc(c.reference)).join(' · ')} -->`;
  return `<${standalone?'h1':'h2'}>${heading}${continuation?` · continued ${esc(continuation)}`:''}</${standalone?'h1':'h2'}>${continuation?'':counts}<p><b>${m.research.available} logical transactions from ${m.research.rawObservations} source observation${m.research.rawObservations===1?'':'s'} · ${m.research.included} included for research.</b> <span class="tag">${esc(m.research.quality)}</span></p>${!continuation&&m.research.duplicateObservations?`<p class="classification-gap"><b>${m.research.duplicateObservations} duplicate observation${m.research.duplicateObservations===1?' was':'s were'} consolidated for display and not double-counted.</b> Underlying source observations remain preserved.</p>`:''}${!continuation&&m.research.possibleDuplicates?`<p class="classification-gap"><b>${m.research.possibleDuplicates} possible duplicate${m.research.possibleDuplicates===1?' requires':'s require'} analyst identity review.</b></p>`:''}${!continuation&&m.research.primary===0?'<div class="classification-gap"><b>Comparable-supported ARV not established.</b> No Primary set, supported adjustments or comparable-derived value is asserted.</div>':''}${rows?`<table class="comp-table"><thead><tr><th>Role / source-reported sale</th><th>Date / price</th><th>Size / proximity / BD-BA</th><th>Selection / rationale</th></tr></thead><tbody>${rows}</tbody></table>`:'<p class="notice">No retained Sale examples. No comparable or ARV is inferred.</p>'}<p class="market-warning"><b>${esc(m.resaleSupport.notice)}</b> Inclusion is a research decision; it does not certify a closing, establish condition or create an adjusted ARV.${m.research.lowestReference?' Lowest retained price: unverified transfer terms and condition; review unusual transactions rather than automatically excluding them.':''}</p>${continuation?'':`${bullets(m.research.findings)}<p class="small">${m.research.listingsCount} retained listing observations are separate and never substituted for Sale prices. Reported dates are not independently verified escrow-close dates. Retrieved ${esc(date(m.research.retrievedAt))}. Private source references remain in audit metadata.</p>`}${privateReferences}`;
}
