function sensitivity(s){
  const max=Math.max(...s.stresses.map(x=>Math.abs(x.effects.netProfit.meanChange)),1);
  // Separate columns keep stress labels out of the chart ink. Values and model
  // order are unchanged; no causal or probabilistic ranking is invented.
  return `<table class="stress-table"><thead><tr><th>Specified stress</th><th>Change in mean profit</th><th>Other paired changes</th></tr></thead><tbody>${s.stresses.map(x=>{const n=x.effects.netProfit.meanChange,w=Math.abs(n)/max*90;return `<tr><td>${esc(names[x.factor])}<br><b>${esc(x.stress)}</b></td><td>${esc(money(n))}<svg class="stress-bar" viewBox="0 0 200 18" role="img" aria-label="Signed mean profit change ${esc(money(n))}"><line x1="100" x2="100" y1="0" y2="18" stroke="#52746f"/><rect x="${n<0?100-w:100}" y="3" width="${w}" height="12" fill="${n<0?'#b5654b':'#277e70'}"/></svg></td><td>Loss frequency: ${number(x.effects.lossProbability.meanChange*100)} percentage points<br>Peak cash: ${money(x.effects.cashRequired.meanChange)}<br>Hold: ${number(x.effects.holdingDays.meanChange)} days</td></tr>`;}).join('')}</tbody></table>`;
}
function simulation(m,a){
  const mc=a.monteCarlo,r=mc.results,f=m.monteCarlo;
  return `<h1>Risk simulation & sensitivity</h1><div class="frequency"><b>${f.loss.count} losses in ${f.loss.iterations.toLocaleString('en-US')} simulated outcomes under the entered ranges.</b><p>This is an observed result inside a bounded, analyst-entered model—not a real-world success probability or guarantee.</p><p>Positive-profit outcomes: ${frequency(f.positive)} · exactly break-even: ${frequency(f.breakEven)} · meets ${esc(targetLabel(m))}: ${frequency(f.target)}.</p></div>
    ${certifiedHistogram(r)}
    <div class="two-col"><section>${table(['Simulated profit','Amount'],[['P10 — lower tenth percentile',money(r.profit.p10)],['P50 — median',money(r.profit.p50)],['P90 — upper ninetieth percentile',money(r.profit.p90)],['Mean',money(r.profit.mean)],['Sample minimum (not worst possible)',money(r.profit.sampleMinimum)]])}</section><section><h2>Reading the simulation</h2><p>${r.expectedLossConditionalOnLoss===null?'No losses occurred under these ranges. Loss severity and unmodeled tail risk are not estimated as zero.':`Average loss when a loss occurred: ${money(r.expectedLossConditionalOnLoss)}.`}</p><p>Bounded triangular inputs are analyst assumptions—not calibrated forecasts. P10 is not a confidence guarantee.</p><p><b>Important omitted risks:</b> title defects, hidden condition, sale failure, changing finance terms, taxes, legal delays and outcomes beyond the entered bounds.</p><p class="small">Seed ${esc(mc.simulation.seed)} · ${mc.simulation.iterations} accepted / ${mc.simulation.samplesDiscarded} discarded. ${esc(RISK_NOTICE)}.</p></section></div>
    <h2>Specified paired stresses</h2>${sensitivity(mc.sensitivity)}<p class="notice"><b>Unmodeled-cost warning:</b> A 30-day holding extension changes modeled profit by ${esc(money(m.deterministicScenarios.find(item=>item.id==='HOLDING_PLUS_30')?.profitChange))} because daily holding-cost inputs are explicitly $0. This is an input-completeness warning—not evidence that delay is cost-free. Delay can also create market, financing, condition, legal and execution losses outside this model.</p><p class="small">Same draws; displayed in model order, not ranked. Differently sized stresses cannot be interpreted as comparable probabilities or causal impacts. Bars show signed dollar changes, not risk likelihood.</p>`;
}
function methodology(m){
  return `<h1>Diligence & distribution readiness</h1><p class="small">Prioritized next actions appear on the executive page. Reverify time-sensitive sources before relying on or circulating conclusions. Analyst notes: ${esc(m.notes||'Not supplied.')}</p>${readinessHtml(m)}${costCompletenessHtml(m)}${reconciliationHtml(m)}${m.monteCarlo?'':'<div class="notice"><b>Monte Carlo not requested.</b> No risk distributions, percentiles or simulated outcome frequencies are presented.</div>'}<h2>Investor inference boundary</h2><div class="two-col"><section><h3>What this report supports</h3><p>A conditional deal hypothesis, source-reported observations, analyst assumptions and reproducible outputs tied to scenario revision ${m.reportMeta.revision}.</p></section><section><h3>What this report does not establish</h3><p>Legal identity, clear title, current payoff, condition, seller availability, adjusted ARV, recommended bid or calibrated probability.</p></section></div>`;
}
function sources(m){
  return `<h1>Sources, dates & licensing boundaries</h1><p>Provider-reported values, analyst assumptions and PI calculations remain distinct. An <b>as-of date</b> describes the evidence; a <b>retrieval date</b> describes when PI obtained it.</p><table class="sources"><colgroup><col style="width:22%"><col style="width:23%"><col style="width:32%"><col style="width:23%"></colgroup><thead><tr><th>Evidence</th><th>Plain-language type</th><th>Human-readable source</th><th>As-of / retrieval date</th></tr></thead><tbody>${m.evidence.map(x=>`<tr><td>${esc(x.label)}</td><td>${esc(x.displayType)}</td><td>${esc(x.source)}</td><td>${esc(x.asOf&&/^\d{4}-/.test(x.asOf)?`As of ${date(x.asOf)}`:x.asOf||'As-of date not returned')}<br>${x.retrievedAt?`Retrieved ${esc(date(x.retrievedAt))}`:'Retrieval date: not recorded / not applicable'}</td></tr>`).join('')}</tbody></table><p class="small">Full raw references, timestamps and internal codes remain in private audit metadata; they are intentionally excluded from this investor-facing document.</p><h2>Distribution & source-rights boundary</h2><p>${esc(m.distribution.providerEvidence)} ${esc(m.distribution.countyEvidence)}</p>${m.distribution.countyNoticeRequired?'<div class="notice"><b>Kern County source notice applies.</b> The complete source notice is retained with this report because Kern County-derived evidence is included.</div>':`<div class="notice"><b>Jurisdiction review:</b> ${esc(m.distribution.jurisdiction||'County not returned')}. No Kern County source evidence is included, so a Kern County notice is not appended and no substitute county disclaimer is invented.</div>`}`;
}
function monteCarloExplanation(){
  return `<section class="monte-carlo-explainer"><h2>Understanding the Monte Carlo Analysis</h2><p>A Monte Carlo simulation explores how an investment's financial results might change when things do not go exactly as planned. Instead of calculating profit using just one selling price, repair budget and timeline, Property Intelligence runs many hypothetical combinations within ranges entered by the analyst.</p><p>For example, the home might sell for less, repairs might cost more, or the project might take longer. The simulation shows how those combinations affect modeled profit.</p><ul><li><b>P10</b> is a lower-profit result: about 10% of the simulated outcomes fall below it.</li><li><b>P50</b> is the middle (median) simulated result.</li><li><b>P90</b> is a higher-profit result: about 90% of the simulated outcomes fall below it.</li></ul><p><b>Important:</b> These percentages describe the simulated outcomes, <b>not the probability of actual investment performance</b>. The analysis cannot predict the future, account for every unexpected expense or guarantee a return. It is only as useful as the assumptions entered.</p></section>`;
}
function technicalProvenance(m,a){
  const mc=a.monteCarlo;
  return `${mc?monteCarloExplanation():''}<h2>Technical provenance appendix</h2><p>This appendix supports reproducibility; it does not strengthen missing property, title, condition or market evidence. Raw scenario identifiers, private attachment paths and sensitive fields remain excluded from the investor-facing document.</p><h2>Immutable report binding</h2>${table(null,[['Report status',m.reportMeta.status],['Scenario',`${m.reportMeta.name} · revision ${m.reportMeta.revision}`],['Scenario saved',m.reportMeta.savedAt],['Report generated',m.reportMeta.generatedAt],['Evidence cutoff',m.reportMeta.evidenceCutoff],['Economics model',a.economicsVersion],['Simulation model',m.reportMeta.monteCarloVersion]])}${mc?`<h2>Uncertainty inputs & reproducibility</h2>${table(['Variable','Distribution (minimum / most likely / maximum)'],mc.materialAssumptions.map(x=>[names[x.variable],x.distribution.family==='CONSTANT'?`Constant: ${number(x.distribution.value)}`:`Triangular: ${[x.distribution.min,x.distribution.mode,x.distribution.max].map(number).join(' / ')}${x.variable.endsWith('Days')?' days':' USD'}`]))}<p><b>Seed ${esc(mc.simulation.seed)}</b> · ${mc.simulation.iterations.toLocaleString('en-US')} accepted outcomes · ${mc.simulation.samplesDiscarded} discarded · PRNG ${esc(mc.simulation.generatorVersion)}.</p><p>${esc(mc.inputs.uncertainty.dependence.rationale)} One analyst scenario (weight 1); residual inputs are treated as conditionally independent.</p><p class="notice"><b>Simulation boundary:</b> Entered ranges are analyst assumptions, not calibrated forecasts. Outcomes outside them are excluded; percentiles are not confidence guarantees, and more iterations cannot replace missing evidence.</p>`:'<div class="notice"><b>Monte Carlo not requested.</b> No distributions, percentiles or risk frequencies are substituted.</div>'}`;
}
export function workspaceReportHtml(p,s,evidence,kind='brief',options={}){
  if(!['brief','full','checklist'].includes(kind)||!s.savedAt)throw new Error('Save a valid scenario before previewing a report.');
  const {model:m,analysis:a}=reportModel(p,s,options);
  if(m.distribution.countyNoticeRequired&&!evidence.disclaimer?.trim())throw new Error('Complete applicable county disclaimer is required for distribution.');
  const id=`<div class="workspace-page-id">PROPERTY INTELLIGENCE <span>${esc(m.reportMeta.readableReference)} · ${esc(s.name)} · r${s.revision} · ${esc(m.reportMeta.status)} · ${esc(reportDate(m.reportMeta.generatedAt))}${s.demonstration?' · DEMONSTRATION':''}</span></div>`;
  const page=(html,cls='')=>`<section class="page ${cls}">${id}${html}</section>`;
  const photos=Array.isArray(options.photos)?options.photos.slice(0,12):[],checklistPages=dueDiligenceChecklistPages(m),photoPages=kind==='full'?propertyPhotoPages(photos):[],sections=kind==='checklist'?checklistPages.map(content=>page(content,'due-diligence-checklist')):[...(kind==='full'?[fullInvestorPackageCover(m,{qaNotForDistribution:options.qaNotForDistribution===true,finalization:options.finalization??null,photos}),...photoPages.map(content=>page(content,'property-photo-page'))]:[]),page(`${finalizationAttribution(options.finalization)}${snapshot(m,a,kind,photos)}`,`snapshot ${kind}`),...(kind==='full'?checklistPages.map(content=>page(content,'due-diligence-checklist')):[])];
  if(kind==='full'){
    const analystAppendix=m.analystEvidence.entries.length>6;
    const supportingDocuments=options.supportingDocuments??[];
    sections.push(page(researchOverview(m,!analystAppendix,supportingDocuments),'research research-overview'),...comparableResearchPages(m,supportingDocuments).map(content=>page(content,'research comparable-research')),...(analystAppendix?[page(analystEvidenceAppendix(m,supportingDocuments),'research analyst-evidence-appendix')]:[]),page(sellerFinancialPositionHtml(m,supportingDocuments),'seller-position-page'),page(economicsInputs(m,a,supportingDocuments),'economics economics-inputs'),page(economicsResults(m,a),'economics economics-results-page'),...(a.monteCarlo?[page(simulation(m,a),'simulation')]:[]),page(methodology(m),'methodology'),page(sources(m),'methodology sources-page'),...(a.monteCarlo?[page(technicalProvenance(m,a),'technical-provenance')]:[]));
  }
  if(m.distribution.countyNoticeRequired)sections.push(page(`<h1>Kern County source disclaimer</h1><p class="small">Complete applicable county notice. Retain with every copy or extract containing this county-derived information.</p><div class="county-text">${evidence.disclaimer.split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}</div>`,'county'));
  const footer=`${m.property.address.value} · ${s.name} r${s.revision} · ${m.reportMeta.status} · generated ${reportDate(m.reportMeta.generatedAt)} PT`;
  const reportLabel=kind==='brief'?'Opportunity Brief':kind==='full'?'Full Investor Package':'Investment Due Diligence Checklist',html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="description" content="${reportLabel} for ${esc(m.property.address.value)}; preliminary saved scenario revision ${s.revision}."><meta name="pi-footer" content="${esc(footer)}"><title>${esc(m.reportMeta.readableReference)} · ${reportLabel} · r${s.revision}</title><style>${reportCss}</style></head><body>${sections.join('')}</body></html>`;
  if(/(?:[A-Za-z]:\\Users\\|data[\\/](?:raw|runtime)[\\/])/i.test(html))throw new Error('REPORT_PRIVATE_PATH_STOP');
  return html;
}
